using Godot;
using MySimulator.Rebuild;
using System;
using System.Collections.Generic;
namespace MySim {
// Isolated real-scene force-driven trial. Production DriveController is not created in this mode.
public partial class NativeTrackTrial : Node3D {
 public int TrackIndex,CarIndex;public Node3D Car;public Node3D[] Wheels;public string Destination;
 NativeSuspensionVehicle body;Camera3D camera;float time,distance,maxSpeed,spin;int frames,groundedSamples,totalSamples;bool initialized,ending;Vector3 start;float initialHeading,sampledYaw,restYaw,maximumUncommandedYaw;bool sampledRest;bool sampled;string turn=System.Environment.GetEnvironmentVariable("MYSIM_NATIVE_TRACK_STEER");readonly List<object> trace=new();readonly Vector3[] wheelHomes=new Vector3[4];
 public override void _Ready(){NativePhysicsClock.Configure();GetViewport().Disable3D=true;camera=new Camera3D {Current=true,Fov=48,Far=4000};AddChild(camera);}
 public override void _PhysicsProcess(double delta){if(ending)return;try{
  if(!initialized){if(++frames<3)return;var circuit=new Circuit(TrackIndex);var position=circuit.Point(.988f);using var query=PhysicsRayQueryParameters3D.Create(new Vector3(position.x,200,position.z),new Vector3(position.x,-200,position.z),1);query.HitBackFaces=true;var hit=GetWorld3D().DirectSpaceState.IntersectRay(query);if(hit.Count==0)throw new Exception("Native track spawn has no source drive surface");var ground=(Vector3)hit["position"];hit.Clear();
   body=new NativeSuspensionVehicle {CarIndex=CarIndex,Position=ground+Vector3.Up*.8f,Rotation=new Vector3(0,circuit.Heading(.988f),0)};body.RecoveredWheelCentres=new Vector3[4];body.RecoveredWheelRadii=new float[4];for(int i=0;i<4;i++){wheelHomes[i]=Wheels[i].Position;body.RecoveredWheelCentres[i]=wheelHomes[i]-Vector3.Up*.65f;body.RecoveredWheelRadii[i]=Wheels[i].GetMeta("radius").AsSingle();}AddChild(body);Car.Reparent(body,false);Car.Position=new Vector3(0,-.65f,0);Car.Rotation=Vector3.Zero;start=body.GlobalPosition;initialHeading=body.Rotation.Y;initialized=true;GD.Print("NATIVE_FORCE_TRIAL_SPAWN track=",TrackIndex," car=",CarIndex);return;
  }
  time+=(float)delta;body.Controls=time<3?new DriverInput(0,0,0):time<7?new DriverInput(.3f,0,turn!=null&&time>=6?SteeringInput.ToSimulation(turn=="right"?.15f:-.15f):0):new DriverInput(0,1,0);
  if(!sampled&&time>=7){sampled=true;sampledYaw=Mathf.Wrap(body.Rotation.Y-initialHeading,-Mathf.Pi,Mathf.Pi);}
  if(!sampledRest&&time>=2.95f){restYaw=Mathf.Wrap(body.Rotation.Y-initialHeading,-Mathf.Pi,Mathf.Pi);sampledRest=true;}if(turn==null&&time>=3)maximumUncommandedYaw=Mathf.Max(maximumUncommandedYaw,Mathf.Abs(Mathf.Wrap(body.Rotation.Y-initialHeading,-Mathf.Pi,Mathf.Pi)));
  var p=body.GlobalPosition;float speed=body.LinearVelocity.Length();if(!float.IsFinite(p.Y)||p.Y<start.Y-10)throw new Exception("Native track chassis fell through the recovered surface");maxSpeed=Mathf.Max(maxSpeed,speed);distance=Mathf.Max(distance,new Vector2(p.X-start.X,p.Z-start.Z).Length());
  if(time>2.5f){totalSamples++;if(body.Contacts>=3)groundedSamples++;}
  spin+=body.LinearVelocity.Dot(body.GlobalBasis.Z)*(float)delta;WheelAnimation.Update(Wheels,spin,body.WheelAngle);for(int i=0;i<4;i++)Wheels[i].Position=wheelHomes[i]+Vector3.Up*(body.RestLength-body.StaticSag-body.SpringLength[i]);var forward=body.GlobalBasis.Z.Normalized();camera.GlobalPosition=p-forward*7+Vector3.Up*2.5f;camera.LookAt(p+forward*3);
  if(frames%120==0)GD.Print("NATIVE_FORCE_TRIAL_PROGRESS t=",time," speed=",speed," contacts=",body.Contacts);
  if(frames++%12==0)trace.Add(new {time,x=p.X,y=p.Y,z=p.Z,speed,contacts=body.Contacts,verticalSpeed=body.LinearVelocity.Y,yaw=body.Rotation.Y,angularSpeed=body.AngularVelocity.Length(),chassisContacts=body.ChassisContacts,loads=(float[])body.Loads.Clone(),tyreForces=System.Array.ConvertAll(body.ContactForces,v=>new[]{v.X,v.Y,v.Z}),groundNormals=System.Array.ConvertAll(body.ContactNormals,v=>new[]{v.X,v.Y,v.Z}),springLengths=(float[])body.SpringLength.Clone()});
  if(time<11)return;bool ok=maxSpeed>8&&distance>10&&speed<1&&groundedSamples>totalSamples*.9f&&(turn==null?sampledRest&&Mathf.Abs(restYaw)<.05f&&maximumUncommandedYaw<.15f:(sampled&&(turn=="right"?sampledYaw<-.02f:sampledYaw>.02f)));ending=true;var result=new {ok,track=TrackIndex,car=CarIndex,wheelCentres=System.Array.ConvertAll(body.RecoveredWheelCentres,v=>new[]{v.X,v.Y,v.Z}),wheelRadii=body.RecoveredWheelRadii,turn,sampledYaw,restYaw,maximumUncommandedYaw,maxSpeed,distance,finalSpeed=speed,groundedSamples,totalSamples,trace,scope="Isolated acceleration/braking on recovered scene; no full lap, traffic, calibration or production acceptance"};System.IO.File.WriteAllText(Destination,System.Text.Json.JsonSerializer.Serialize(result,new System.Text.Json.JsonSerializerOptions {WriteIndented=true}));GD.Print(ok?"PASS force-driven native track trial":"FAIL force-driven native track trial");Finish(ok);
 }catch(Exception e){GD.PushError(e.ToString());ending=true;CleanExit.Request(this,1);}}
 async void Finish(bool ok){string shot=System.Environment.GetEnvironmentVariable("MYSIM_SHOT");if(shot!=null){GetViewport().Disable3D=false;await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);var error=GetViewport().GetTexture().GetImage().SavePng(shot);if(error!=Error.Ok){GD.PushError("Native physical scene capture failed: "+error);ok=false;}}CleanExit.Request(this,ok?0:1);}
}
}
